SELECT * FROM ( SELECT m.*, ROWNUM AS rnum FROM ( SELECT m_id AS mId, m_username AS mUsername, m_nickname AS mNickname, m_email AS mEmail, m_phone AS mPhone, m_birth AS mBirth, m_gender AS mGender, m_role AS mRole, m_status AS mStatus, m_login_type AS mLoginType, m_regdate AS mRegdate FROM member WHERE m_role != 'ADMIN'
AND ( LOWER(m_username) LIKE LOWER('%' || #{search} || '%') OR LOWER(m_nickname) LIKE LOWER('%' || #{search} || '%') OR LOWER(m_email) LIKE LOWER('%' || #{search} || '%') )
AND m_status = #{status}
ORDER BY m_regdate DESC ) m WHERE ROWNUM <= #{offset} + #{size} ) WHERE rnum > #{offset}

SELECT COUNT(*) FROM member WHERE m_role != 'ADMIN'
AND ( LOWER(m_username) LIKE LOWER('%' || #{search} || '%') OR LOWER(m_nickname) LIKE LOWER('%' || #{search} || '%') OR LOWER(m_email) LIKE LOWER('%' || #{search} || '%') )
AND m_status = #{status}

SELECT * FROM ( SELECT r.*, ROWNUM AS rnum FROM ( SELECT r.rv_id AS rvId, r.m_id AS mId, r.contentid AS contentid, r.rv_content AS rvContent, r.rv_rating AS rvRating, r.created_at AS createdAt, m.m_nickname AS authorNickname FROM review r LEFT JOIN member m ON r.m_id = m.m_id WHERE 1=1
AND ( LOWER(r.rv_content) LIKE LOWER('%' || #{search} || '%') OR LOWER(m.m_nickname) LIKE LOWER('%' || #{search} || '%') OR r.contentid LIKE '%' || #{search} || '%' )
ORDER BY r.created_at DESC ) r WHERE ROWNUM <= #{offset} + #{size} ) WHERE rnum > #{offset}

